package mz.co.aprendaacodar.enrollment.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.course.entity.Course;import mz.co.aprendaacodar.user.entity.User;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="course_enrollments",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","course_id"})) public class CourseEnrollment extends BaseEntity {
 @ManyToOne(optional=false,fetch=FetchType.LAZY) private User student;@ManyToOne(optional=false,fetch=FetchType.LAZY) private Course course;@Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private EnrollmentStatus status;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private EnrollmentSource source;@Column(nullable=false,precision=12,scale=2) private BigDecimal agreedPrice;@Column(nullable=false,length=3) private String currency;@Column(nullable=false) private Instant enrolledAt;private Instant activatedAt;private Instant revokedAt;@ManyToOne(fetch=FetchType.LAZY) private User revokedBy;@Column(columnDefinition="TEXT") private String revocationReason;@ManyToOne(fetch=FetchType.LAZY) private User grantedBy;
 protected CourseEnrollment(){}public CourseEnrollment(User s,Course c,EnrollmentStatus st,EnrollmentSource src,BigDecimal price,String currency){student=s;course=c;status=st;source=src;agreedPrice=price;this.currency=currency;enrolledAt=Instant.now();if(st==EnrollmentStatus.ACTIVE)activatedAt=Instant.now();}
 public void underReview(){status=EnrollmentStatus.UNDER_REVIEW;}public void reject(){status=EnrollmentStatus.REJECTED;}public void activate(User admin,EnrollmentSource src){status=EnrollmentStatus.ACTIVE;source=src;activatedAt=Instant.now();grantedBy=admin;revokedAt=null;revokedBy=null;revocationReason=null;}public void revoke(User admin,String reason){status=EnrollmentStatus.REVOKED;revokedAt=Instant.now();revokedBy=admin;revocationReason=reason;}
 public User getStudent(){return student;}public Course getCourse(){return course;}public EnrollmentStatus getStatus(){return status;}public EnrollmentSource getSource(){return source;}public BigDecimal getAgreedPrice(){return agreedPrice;}public String getCurrency(){return currency;}public Instant getEnrolledAt(){return enrolledAt;}public Instant getActivatedAt(){return activatedAt;}public Instant getRevokedAt(){return revokedAt;}public String getRevocationReason(){return revocationReason;}
}
